from typing import TypedDict

class Receiver(TypedDict):
    key: int

class FirstSource(TypedDict):
    key: str

class SecondSource(TypedDict):
    key: str
    unrelated: bytes

def probe(target: Receiver, source: FirstSource | SecondSource) -> None:
    target.update(source)

